(6578829, 980032, 64733, '<td valign="top">I didn''t even notice the bee at first.  Very nice.</td>', 'I didn''t even notice the bee at first.  Very nice.', '2011-10-29 10:54:49.000000', NULL, 1),
(6578830, 980094, 64733, '<td valign="top">I would have rather gone more abstract on this image, cropping the cars in the background.  I get a little lost in this image.</td>', 'I would have rather gone more abstract on this image, cropping the cars in the background.  I get a little lost in this image.', '2011-10-29 10:57:13.000000', NULL, 1),
(6578831, 979535, 64733, '<td valign="top">Very cool color contrasts.  Focal point is clear.  Vignetting is effective.  My only comment is that the peeled paint in the background is a distraction. Would have maybe cropped closer to the subject.</td>', 'Very cool color contrasts.  Focal point is clear.  Vignetting is effective.  My only comment is that the peeled paint in the background is a distraction. Would have maybe cropped closer to the subject.', '2011-10-29 10:57:40.000000', NULL, 1),
(6578832, 980004, 64733, '<td valign="top">I''ma sucker for car photos.  Would have probably removed the leaves in the road to really mask the size relationship.  Love the background and lighting. Makes me think the car could move on its own.</td>', 'I''ma sucker for car photos.  Would have probably removed the leaves in the road to really mask the size relationship.  Love the background and lighting. Makes me think the car could move on its own.', '2011-10-29 10:57:45.000000', NULL, 1),
(6578833, 979605, 64733, '<td valign="top">You could have entered this in the Candid competition this week!  Nice way to capture an all-too familiar everyday occurrence, life on the iPhone!</td>', 'You could have entered this in the Candid competition this week!  Nice way to capture an all-too familiar everyday occurrence, life on the iPhone!', '2011-10-29 10:57:47.000000', NULL, 1),
(6578834, 980082, 64733, '<td valign="top">Very cute.  I like the use of dark contrast.</td>', 'Very cute.  I like the use of dark contrast.', '2011-10-29 10:57:50.000000', NULL, 1),
(6578835, 979695, 64733, '<td valign="top">This works very well for me.  Composition is interesting.  Colors are amazing.  Exposure is near perfect.  Well done!</td>', 'This works very well for me.  Composition is interesting.  Colors are amazing.  Exposure is near perfect.  Well done!', '2011-10-29 10:57:51.000000', NULL, 1),
(6578836, 979646, 64733, '<td valign="top">Good use of DOF.  I like  the way you captured the oxidation.  Rust does have a lot of color!</td>', 'Good use of DOF.  I like  the way you captured the oxidation.  Rust does have a lot of color!', '2011-10-29 10:57:54.000000', NULL, 1),
