(6578841, 980060, 64733, '<td valign="top">I like the repetitive pattern, but the image seems grainy on my screen.  Nice composition the way it leads the eye across the page/screen.</td>', 'I like the repetitive pattern, but the image seems grainy on my screen.  Nice composition the way it leads the eye across the page/screen.', '2011-10-29 10:58:40.000000', NULL, 1),
(6578842, 980023, 64733, '<td valign="top">Almost looks like an aerial photo of a suflur bed or something.  Interesting composition.</td>', 'Almost looks like an aerial photo of a suflur bed or something.  Interesting composition.', '2011-10-29 10:58:47.000000', NULL, 1),
(6578843, 979835, 64733, '<td valign="top">Eerie shot.  Good to this time of year.  Would be interesting to see a little more of what''s behind the bag.  What''s it protecting?</td>', 'Eerie shot.  Good to this time of year.  Would be interesting to see a little more of what''s behind the bag.  What''s it protecting?', '2011-10-29 10:58:54.000000', NULL, 1),
(6578844, 979888, 64733, '<td valign="top">Very 80''s!  Would love to see that sunrise unmasked!  Difficult shot to make work and I think you did a good job.</td>', 'Very 80''s!  Would love to see that sunrise unmasked!  Difficult shot to make work and I think you did a good job.', '2011-10-29 10:58:57.000000', NULL, 1),
(6578845, 979579, 64733, '<td valign="top">I feel like the graffiti wants to be the central focus of the image, but we are led to the pavement markings which are not as interesting as the graffiti.</td>', 'I feel like the graffiti wants to be the central focus of the image, but we are led to the pavement markings which are not as interesting as the graffiti.', '2011-10-29 10:59:13.000000', NULL, 1),
