(6579686, 979834, 67697, '<td valign="top">I really looooooove this perspective.  Incredibly clever idea.  The glowing flower is cool too.  The only thing that takes away from this is that you skipped a smidge in your remasking (the triangle over the first strap.)  Still, I like the uniqueness of this photo.</td>', 'I really looooooove this perspective.  Incredibly clever idea.  The glowing flower is cool too.  The only thing that takes away from this is that you skipped a smidge in your remasking (the triangle over the first strap.)  Still, I like the uniqueness of this photo.', '2011-10-30 23:05:00.000000', NULL, 1),
(6579687, 979535, 67697, '<td valign="top">I really love all the rich colors in this.  The red splotches really help pull out the color of the eye too.</td>', 'I really love all the rich colors in this.  The red splotches really help pull out the color of the eye too.', '2011-10-30 23:05:54.000000', NULL, 1),
(6579688, 979919, 67697, '<td valign="top">I love your way of adding some motion to complement the stationary object.</td>', 'I love your way of adding some motion to complement the stationary object.', '2011-10-30 23:06:26.000000', NULL, 1),
(6579689, 979993, 67697, '<td valign="top">Love the red and gray contrast.  Beautiful use of shallow DOF.</td>', 'Love the red and gray contrast.  Beautiful use of shallow DOF.', '2011-10-30 23:06:51.000000', NULL, 1),
(6579690, 979839, 67697, '<td valign="top">This is no doubt a macro lol.  Love the strong black and white contrasts.</td>', 'This is no doubt a macro lol.  Love the strong black and white contrasts.', '2011-10-30 23:07:17.000000', NULL, 1);
